/* global OffscreenCanvas, btoa, URL, console, Buffer */
// Regenerates tests/fixtures/encoded.ts: small JPEG/WebP fixtures drawn by Lovert's own code and encoded once
// by Chromium, stored as base64 so every browser project gets the same bytes (WebKit cannot encode WebP inputs).
// Usage right: generated here, no third-party content. Run: node tests/fixtures/make-encoded.mjs
import { writeFileSync } from 'node:fs';
import { chromium } from '@playwright/test';

const browser = await chromium.launch();
const page = await browser.newPage();
const enc = (spec) =>
  page.evaluate(async ({ w, h, type, q, draw }) => {
    const c = new OffscreenCanvas(w, h);
    const x = c.getContext('2d');
    for (const [style, rx, ry, rw, rh] of draw) {
      x.fillStyle = style;
      x.fillRect(rx, ry, rw, rh);
    }
    const b = await c.convertToBlob({ type, quality: q });
    if (b.type !== type) throw new Error(`cannot encode ${type}`);
    const u = new Uint8Array(await b.arrayBuffer());
    let s = '';
    for (const v of u) s += String.fromCharCode(v);
    return btoa(s);
  }, spec);

const out = {
  // 240×120: white, red block stored top-left (0..80, 0..40), blue block stored bottom-right. EXIF tests rotate this.
  asymJpeg: await enc({ w: 240, h: 120, type: 'image/jpeg', q: 0.95, draw: [['#fff', 0, 0, 240, 120], ['#f00', 0, 0, 80, 40], ['#00f', 200, 100, 40, 20]] }),
  // 160×80 JPEG, left half green, right half blue: a second, distinguishable input.
  splitJpeg: await enc({ w: 160, h: 80, type: 'image/jpeg', q: 0.95, draw: [['#0c0', 0, 0, 80, 80], ['#00f', 80, 0, 80, 80]] }),
  // 200×100 WebP lossless (quality 1): left half fully transparent, right half red.
  alphaWebp: await enc({ w: 200, h: 100, type: 'image/webp', q: 1, draw: [['#f00', 100, 0, 100, 100]] }),
  // 120×60 opaque WebP lossless, solid blue / solid red: animation frames and a plain opaque input.
  blueWebp: await enc({ w: 120, h: 60, type: 'image/webp', q: 1, draw: [['#00f', 0, 0, 120, 60]] }),
  redWebp: await enc({ w: 120, h: 60, type: 'image/webp', q: 1, draw: [['#f00', 0, 0, 120, 60]] }),
};
await browser.close();
writeFileSync(
  new URL('./encoded.ts', import.meta.url),
  `/** Generated by tests/fixtures/make-encoded.mjs (Chromium encoder, fixed drawings). Do not edit by hand. */\n` +
    Object.entries(out).map(([k, v]) => `export const ${k} = Buffer.from('${v}', 'base64');`).join('\n') + '\n',
);
console.log(Object.fromEntries(Object.entries(out).map(([k, v]) => [k, Buffer.from(v, 'base64').length])));
